package com.example.demo.config; import org.springframework.boot.web.servlet.ServletRegistrationBean; import org.springframework.context.ApplicationContext; import org.springframework.context.annotation.*; import org.springframework.core.io.ClassPathResource; import org.springframework.ws.config.annotation.EnableWs; import org.springframework.ws.transport.http.MessageDispatcherServlet; import org.springframework.ws.wsdl.wsdl11.DefaultWsdl11Definition; import org.springframework.xml.xsd.*; @EnableWs @Configuration public class WebServiceConfig { @Bean public ServletRegistrationBean<MessageDispatcherServlet> messageDispatcherServlet(ApplicationContext c){MessageDispatcherServlet s=new MessageDispatcherServlet();s.setApplicationContext(c);s.setTransformWsdlLocations(true);return new ServletRegistrationBean<>(s,"/ws/*");} @Bean(name="users") public DefaultWsdl11Definition users(XsdSchema schema){DefaultWsdl11Definition d=new DefaultWsdl11Definition();d.setPortTypeName("UsersPort");d.setLocationUri("/ws");d.setTargetNamespace("http://example.com/demo/webservice");d.setSchema(schema);return d;} @Bean public XsdSchema usersSchema(){return new SimpleXsdSchema(new ClassPathResource("users.xsd"));} }